$files = Get-ChildItem -Recurse -Filter *.dart -Path lib; foreach ($file in $files) {$c = Get-Content $file.FullName -Raw; if ($c -match "Platform\.") { if ($c -notmatch "kIsWeb") { $c = "import 'package:flutter/foundation.dart';`n" + $c }; $c = $c -replace "if\s*\((Platform\.isWindows\s*\|\|\s*Platform\.isLinux\s*\|\|\s*Platform\.isMacOS)\)", "if (!kIsWeb && (`$1))"; $c =$c -replace "Platform\.isWindows\s*\|\|\s*Platform\.isLinux\s*\|\|\s*Platform\.isMacOS", "!kIsWeb"; $c =$c -replace "Platform\.pathSeparator", "'/'"; $c =$c -replace "Platform\.resolvedExecutable", "''"; Set-Content $file.FullName $c -NoNewline } }
